use std::net::SocketAddr;
use opentelemetry::global;
use opentelemetry::metrics::Counter;
use tonic::{transport::Server, Request, Response, Status};
use tracing::instrument;

// Generated by build.rs into src/proto/. Committed so reviewers see the wire
// shape without running cargo first; see DESIGN_DECISIONS.md.
pub mod hello {
    include!("proto/hello.rs");
}
mod telemetry;

use hello::greeter_server::{Greeter, GreeterServer};
use hello::{HelloReply, HelloRequest};

struct GreeterSvc {
    hello_counter: Counter<u64>,
}

#[tonic::async_trait]
impl Greeter for GreeterSvc {
    #[instrument(skip(self, req))]
    async fn say_hello(
        &self,
        req: Request<HelloRequest>,
    ) -> Result<Response<HelloReply>, Status> {
        let name = req.into_inner().name;
        let name = if name.is_empty() { "world".to_string() } else { name };
        self.hello_counter.add(1, &[]);
        Ok(Response::new(HelloReply {
            message: format!("hello, {name}"),
        }))
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let _guard = telemetry::init()?;

    let meter = global::meter("server");
    let hello_counter = meter
        .u64_counter("say_hello_total")
        .with_description("Total say_hello gRPC requests")
        .build();

    let addr: SocketAddr = std::env::var("SERVER_ADDR")
        .unwrap_or_else(|_| "0.0.0.0:50051".to_string())
        .parse()?;
    tracing::info!(%addr, "server: listening");

    Server::builder()
        .add_service(GreeterServer::new(GreeterSvc { hello_counter }))
        .serve(addr)
        .await?;

    Ok(())
}
